/* ---------- online record: seed 1..BANK*20 ---------- */
function onlineRec(seed){
  var k=seed-1,f=BANK[k%BANK.length],vi=((k/BANK.length)|0)%VB.length;
  var rnd=prng(((seed*2654435761)>>>0)||3);
  var part=VB[vi](f,seed,rnd);
  part.id=PREFIX+String(seed).padStart(7,'0');
  part.slug=CFG.slug;part.record_kind=CFG.kind;part.category=f.cat;
  part.source='online';part.source_ref=f.ref;part.fact_key=f.k;part.creation_mode='CURATED';
  part._seed=seed;
  return part;
}
/* ---------- signature record: seed 2001..1000000 ---------- */
function sigRec(seed){
  var rnd=prng(((seed*2246822519)>>>0)||7);
  var A=pick(rnd,CFG.sig);
  var nm='Signature '+pick(rnd,A.a)+' '+pick(rnd,A.b);
  var title=nm+' '+A.label;
  var steps=shuffle(rnd,A.steps).slice(0,ri(rnd,4,Math.min(7,A.steps.length)));
  var body=A.lead.replace(/\{N\}/g,nm)+'\n\n'+A.close.replace(/\{N\}/g,nm);
  var rec={id:PREFIX+String(seed).padStart(7,'0'),slug:CFG.slug,record_kind:CFG.kind,
    category:pick(rnd,CATS),record_type:A.type,title:title,
    summary:dot(A.sum.replace(/\{N\}/g,nm)),
    body:body,items:steps.map(function(s,i){return (i+1)+'. '+s;}),
    source:'signature',creation_mode:'SIGNATURE-GENERATED',simulated:true,
    disclosure:'Signature-generated '+A.label.toLowerCase()+'. Illustrative content created by the '+CFG.ai+' generator for planning and exploration; it is not a real-world observation or measurement.',
    _seed:seed};
  if(A.qkind){rec.quant=mkQuant(A.qkind,CFG.qranges[A.qkind],rnd,'Simulated inputs for illustration.');}
  return rec;
}
function generate(seed,opts){
  opts=opts||{};
  var rec=(seed>=1&&seed<=BANK.length*VB.length)?onlineRec(seed):sigRec(seed);
  if(opts.category&&CATS.indexOf(opts.category)>=0)rec.category=opts.category;
  return rec;
}
/* ---------- validation: real invariants, recomputation, cross-checks ---------- */
var IDRE=new RegExp('^'+PREFIX+'\\d{7}$');
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not-object']};
  if(!IDRE.test(r.id||''))e.push('id');
  if(r.record_kind!==CFG.kind)e.push('record_kind');
  if(CATS.indexOf(r.category)<0)e.push('category');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.summary!=='string'||r.summary.length<20||!/[.!?]$/.test(r.summary.trim()))e.push('summary');
  if(typeof r.body!=='string'||r.body.length<120||(r.body.match(/[.!?]/g)||[]).length<2)e.push('body');
  if(r.items!==undefined){
    if(!Array.isArray(r.items)||r.items.length<2||r.items.length>12)e.push('items-len');
    else r.items.forEach(function(x){if(typeof x!=='string'||!x.trim())e.push('items-val');});
  }
  if(r.source==='online'){
    if(typeof r.source_ref!=='string'||!r.source_ref.trim())e.push('source_ref');
    if(r.creation_mode!=='CURATED')e.push('creation_mode');
    var f=null;for(var i=0;i<BANK.length;i++)if(BANK[i].k===r.fact_key){f=BANK[i];break;}
    if(!f)e.push('fact_key');
    else if(r.title.toLowerCase().indexOf(f.n.toLowerCase())<0)e.push('title-fact');
  }else if(r.source==='signature'){
    if(r.creation_mode!=='SIGNATURE-GENERATED')e.push('creation_mode');
    if((r.title||'').indexOf('Signature ')!==0)e.push('title-sig');
    if(typeof r.disclosure!=='string'||r.disclosure.indexOf('Signature-generated')<0)e.push('disclosure');
    if(r.quant&&r.simulated!==true)e.push('simulated');
  }else e.push('source');
  if(r.record_type==='illustrative-scenario'&&String(r.body).toLowerCase().indexOf('illustrative')<0)e.push('illustrative-mark');
  if(r.quant){
    var q=r.quant;
    if(!QK[q.kind])e.push('quant-kind');
    else if(Math.abs(QK[q.kind].f(q.inputs)-q.result)>QK[q.kind].tol)e.push('quant-mismatch');
  }
  return{ok:!e.length,errors:e};
}
